228	    /**
229	     * The idempotency key supplied on the current create request, read from its {@code Idempotency-Key}
230	     * header. A blank value is treated as absent.
231	     *
232	     * @return the trimmed {@code Idempotency-Key} header, or {@code null} when it is absent or blank
233	     */
234	    private String currentIdempotencyKey() {
235	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
236	            String header = attributes.getRequest().getHeader("Idempotency-Key");
237	            if (header != null && !header.isBlank()) {
238	                return header.trim();
239	            }
240	        }
241	        return null;
242	    }
243	
244	    /**
245	     * Finds the owner originally created under the given idempotency key, so a repeated create carrying
246	     * an already-seen key returns that owner instead of creating a duplicate. The lowest-id match is
247	     * returned when more than one owner somehow carries the key.
248	     *
249	     * @param idempotencyKey the create request's idempotency key
250	     * @return the owner first created under the key, or {@code null} when the key has not been seen
251	     */
252	    private Owner findOwnerByIdempotencyKey(String idempotencyKey) {
253	        return this.clinicService.findAllOwners().stream()
254	            .filter(existing -> idempotencyKey.equals(existing.getIdempotencyKey()))
255	            .min(java.util.Comparator.comparing(Owner::getId))
256	            .orElse(null);
257	    }
