262	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
263	        if (currentOwner == null) {
264	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
265	        }
266	        currentOwner.setAddress(ownerFieldsDto.getAddress());
267	        currentOwner.setCity(ownerFieldsDto.getCity());
268	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
269	        currentOwner.setLastName(ownerFieldsDto.getLastName());
270	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
271	        this.clinicService.saveOwner(currentOwner);
272	        return new ResponseEntity<>(toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
273	    }
