353	    /**
354	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
355	     * offending field is collected so the caller learns exactly which values must be supplied.
356	     *
357	     * @param ownerFieldsDto the submitted owner payload
358	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
359	     *         telephone is missing or blank
360	     */
361	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
362	        List<String> missingFields = new ArrayList<>();
363	        if (isBlank(ownerFieldsDto.getFirstName())) {
364	            missingFields.add("firstName");
365	        }
366	        if (isBlank(ownerFieldsDto.getLastName())) {
367	            missingFields.add("lastName");
368	        }
369	        if (isBlank(ownerFieldsDto.getAddressLine1())
370	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
371	            missingFields.add("address");
372	        }
373	        if (isBlank(ownerFieldsDto.getCity())) {
374	            missingFields.add("city");
375	        }
376	        if (isBlank(ownerFieldsDto.getTelephone())) {
377	            missingFields.add("telephone");
378	        }
379	        if (!missingFields.isEmpty()) {
380	            throw new MissingOwnerFieldsException(missingFields);
381	        }
382	    }
383	
384	    private boolean isBlank(String value) {
385	        return value == null || value.isBlank();
386	    }
387	
388	    /**
389	     * Rejects an owner create whose supplied {@code registrationDate} is later than the server's
390	     * current date. A registration date may not lie in the future; a value equal to today or in the
391	     * past is accepted, and an absent date is left to default to the server date.
392	     *
393	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
394	     * @throws InvalidOwnerFieldsException if the supplied date is after the server's current date
395	     */
396	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
397	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
398	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
399	        }
400	    }
401	
402	    /**
403	     * Counts the existing owners who, before this create, already share the given first and last name.
404	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
405	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
406	     * case or spacing still count as the same name.
407	     *
408	     * @param firstName the first name of the owner being created
409	     * @param lastName the last name of the owner being created
410	     * @return the number of existing owners sharing both names (zero when none)
411	     */
412	    private int countNamesakes(String firstName, String lastName) {
413	        String first = normalizeHouseholdField(firstName);
414	        String last = normalizeHouseholdField(lastName);
415	        return (int) this.clinicService.findAllOwners().stream()
416	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
417	                && normalizeHouseholdField(existing.getLastName()).equals(last))
418	            .count();
419	    }
420	
421	    /**
422	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
423	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
424	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
425	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
426	     * more owners the create is rejected as a conflict.
427	     *
428	     * @param city the city of the owner being created
429	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
430	     */
431	    /**
432	     * Rejects an owner create once the maximum number of owners have already been registered on the
433	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
434	     * which is always a business day (a weekend effective date is rolled forward to the following
435	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
436	     * business day the create is rejected as too many requests. Because a weekend effective date is
437	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
438	     *
439	     * @param businessDay the adjusted business day the owner being created would be registered on
440	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
441	     */
442	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
443	        long ownersOnDay = this.clinicService.findAllOwners().stream()
444	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
445	            .count();
446	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
447	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
448	        }
449	    }
450	
451	    /**
452	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
453	     * forward, and a date that lands on a listed public holiday is likewise rolled forward, until the
454	     * result is a weekday that is not a public holiday; a weekday that is not a holiday is returned
455	     * unchanged. This applies whether the date was supplied on the request or defaulted to the
456	     * server's current date.
457	     *
458	     * @param date the effective registration date (supplied or defaulted)
459	     * @return the first non-holiday weekday on or after the supplied date
460	     */
461	    /**
462	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
463	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
464	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
465	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
466	     *
467	     * @return {@code true} when more than the threshold number of owners are already registered on
468	     *         today's business day, otherwise {@code false}
469	     */
470	    private boolean isBulkSignupWarningActive() {
471	        LocalDate today = toBusinessDay(LocalDate.now());
472	        long ownersToday = this.clinicService.findAllOwners().stream()
473	            .filter(existing -> today.equals(existing.getRegistrationDate()))
474	            .count();
475	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
476	    }
477	
478	    private LocalDate toBusinessDay(LocalDate date) {
479	        LocalDate adjusted = switch (date.getDayOfWeek()) {
480	            case SATURDAY -> date.plusDays(2);
481	            case SUNDAY -> date.plusDays(1);
482	            default -> date;
483	        };
484	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
485	            adjusted = adjusted.plusDays(1);
486	        }
487	        return adjusted;
488	    }
489	
490	    private boolean isWeekend(LocalDate date) {
491	        return switch (date.getDayOfWeek()) {
492	            case SATURDAY, SUNDAY -> true;
493	            default -> false;
494	        };
495	    }
496	
497	    private void rejectCityAtCapacity(String city) {
498	        String normalizedCity = normalizeHouseholdField(city);
499	        long ownersInCity = this.clinicService.findAllOwners().stream()
500	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
501	            .count();
502	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
503	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
504	        }
505	    }
506	
507	    /**
508	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
509	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
510	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
511	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). Two owners resolve
512	     * to the same base code only when they share a region and produce the same telephone-and-last-name
513	     * hash; when the computed code collides with an existing owner's customer code it is de-duplicated
514	     * by appending '-&lt;n&gt;' with the smallest {@code n} of 2 or more that makes it unique.
515	     *
516	     * @param postcode the owner's postcode, used first to derive the region
517	     * @param city the owner's city, used to derive the region when the postcode maps to none
518	     * @param normalizedTelephone the owner's normalized (E.164) telephone
519	     * @param lastName the owner's last name
520	     * @return the formatted, de-duplicated customer code
521	     */
522	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
523	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
524	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
525	        String baseCode = region + "-" + hash8;
526	        return deduplicateCustomerCode(baseCode);
527	    }
528	
529	    /**
530	     * De-duplicates a computed customer code against every existing owner's customer code. When no
531	     * existing owner already carries the base code it is returned unchanged; otherwise '-&lt;n&gt;' is
532	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner holds.
533	     *
534	     * @param baseCode the computed, formatted customer code before de-duplication
535	     * @return the base code when unique, otherwise the base code suffixed with '-&lt;n&gt;'
536	     */
537	    private String deduplicateCustomerCode(String baseCode) {
538	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
539	            .map(Owner::getCustomerCode)
540	            .filter(java.util.Objects::nonNull)
541	            .collect(java.util.stream.Collectors.toSet());
542	        if (!existingCodes.contains(baseCode)) {
543	            return baseCode;
544	        }
545	        int n = 2;
546	        while (existingCodes.contains(baseCode + "-" + n)) {
547	            n++;
548	        }
549	        return baseCode + "-" + n;
550	    }
551	
552	    /**
553	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
554	     * customerCode is the owner's customer code and YY is the last two digits of the fiscal year (the
555	     * fiscal year starts on 1 July) that the business-day-adjusted registrationDate falls in
556	     * (e.g. 'NSW-1A2B3C4D-M27').
557	     *
558	     * @param customerCode the owner's customer code
559	     * @param registrationDate the owner's business-day-adjusted registration date
560	     * @return the formatted membership number
561	     */
562	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
563	        String yy = String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
564	        return customerCode + "-M" + yy;
565	    }
566	
567	    /**
568	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
569	     * country calling code. Australia ('+61') uses 9 national digits and the North American
570	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
571	     * E.164 length (8 to 15 digits overall).
572	     */
573	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
574	        java.util.Map.of("61", 9, "1", 10);
575	
576	    /**
577	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
578	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
579	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
580	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
581	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
582	     * E.164 string is what gets stored and returned.
583	     *
584	     * @param telephone the raw telephone value from the request
585	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
586	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
587	     *         national number has the wrong length for its country code
588	     */
589	    private String normalizeTelephone(String telephone) {
590	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
591	        String e164;
592	        if (cleaned.startsWith("+")) {
593	            e164 = cleaned;
594	        } else {
595	            String national = cleaned;
596	            if (national.startsWith("0")) {
597	                national = national.substring(1);
598	            }
599	            e164 = "+61" + national;
600	        }
601	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
602	            throw new InvalidOwnerFieldsException(List.of("telephone"));
603	        }
604	        validateNationalNumberLength(e164);
605	        return e164;
606	    }
607	
608	    /**
609	     * Rejects an E.164 telephone whose national number does not have the exact length its country
610	     * calling code requires. The digits after the leading '+' are split into the longest matching
611	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
612	     * code is known and the national number's length differs from the required count the telephone is
613	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
614	     *
615	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
616	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
617	     */
618	    private void validateNationalNumberLength(String e164) {
619	        String digits = e164.substring(1);
620	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
621	            String countryCode = digits.substring(0, codeLength);
622	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
623	            if (requiredNationalLength != null) {
624	                int nationalLength = digits.length() - codeLength;
625	                if (nationalLength != requiredNationalLength) {
626	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
627	                }
628	                return;
629	            }
630	        }
631	    }
632	
633	    /**
634	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
635	     * left unset. When a value is present it must be a syntactically valid address whose domain is not
636	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the normalized form
637	     * stored and returned is the value lower-cased.
638	     *
639	     * @param email the raw email value from the request, or {@code null} when none was supplied
640	     * @return the lower-cased email, or {@code null} when no email was supplied
641	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address or
642	     *         its domain is on the disposable-domain blocklist
643	     */
644	    private String normalizeEmail(String email) {
645	        if (email == null || email.isBlank()) {
646	            return null;
647	        }
648	        if (!EMAIL_PATTERN.matcher(email).matches()) {
649	            throw new InvalidOwnerFieldsException(List.of("email"));
650	        }
651	        String normalized = email.toLowerCase(Locale.ROOT);
652	        String domain = normalized.substring(normalized.indexOf('@') + 1);
653	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
654	            throw new InvalidOwnerFieldsException(List.of("email"));
655	        }
656	        return normalized;
657	    }
658	
659	    /**
660	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
661	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
662	     * When present it must be exactly four digits and, when the owner's city maps to a known region
663	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
664	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
665	     * region accepts any four-digit postcode.
666	     *
667	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
668	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
669	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
670	     *         for the city's region
671	     */
672	    private void validatePostcode(String city, String postcode) {
673	        if (postcode == null || postcode.isBlank()) {
674	            return;
675	        }
676	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
677	            throw new InvalidOwnerFieldsException(List.of("postcode"));
678	        }
679	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
680	        if (range == null) {
681	            return;
682	        }
683	        int value = Integer.parseInt(postcode);
684	        if (value < range[0] || value > range[1]) {
685	            throw new InvalidOwnerFieldsException(List.of("postcode"));
686	        }
687	    }
688	
689	    /**
690	     * Resolves an owner's address from the supplied structured and flat fields, preferring the
691	     * structured form. Whichever address fields were supplied are normalized (see
692	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
693	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (an
694	     * absent or blank {@code addressLine2} is cleared) and the composed {@code address} is the
695	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
696	     * appended when the latter is present. When no {@code addressLine1} is supplied the flat
697	     * {@code address} is used unchanged for backward compatibility and the structured lines are
698	     * cleared. The composed {@code address} is what every later step reads.
699	     *
700	     * @param owner the owner being created, mapped from the request but not yet normalized
701	     */
702	    private void applyAddress(Owner owner) {
703	        String line1 = normalizeAddress(owner.getAddressLine1());
704	        String line2 = normalizeAddress(owner.getAddressLine2());
705	        String flat = normalizeAddress(owner.getAddress());
706	        if (!line1.isEmpty()) {
707	            owner.setAddressLine1(line1);
708	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
709	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
710	        } else {
711	            owner.setAddressLine1(null);
712	            owner.setAddressLine2(null);
713	            owner.setAddress(flat);
714	        }
715	    }
716	
717	    /**
718	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
719	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
720	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
721	     * normalized form is what gets stored, returned and used for every address comparison (the
722	     * required-field check, household duplicate detection and the shared household id).
723	     *
724	     * @param address the raw address value from the request, or {@code null}
725	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
726	     */
727	    private String normalizeAddress(String address) {
728	        if (address == null) {
729	            return "";
730	        }
731	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
732	        if (collapsed.isEmpty()) {
733	            return "";
734	        }
735	        String[] tokens = collapsed.split(" ");
736	        for (int i = 0; i < tokens.length; i++) {
737	            switch (tokens[i]) {
738	                case "ST" -> tokens[i] = "STREET";
739	                case "RD" -> tokens[i] = "ROAD";
740	                case "AVE" -> tokens[i] = "AVENUE";
741	                default -> { }
742	            }
743	        }
744	        return String.join(" ", tokens);
745	    }
746	
747	    /**
748	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
749	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
750	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
751	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
752	     * so two members of one household with different telephones have different keys and are both
753	     * allowed; only an owner whose entire key is identical is a duplicate.
754	     *
755	     * @param owner the owner being created, with its telephone, email and householdId already resolved
756	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
757	     */
758	    private void rejectDuplicateIdentity(Owner owner) {
759	        String identityKey = owner.getIdentityKey();
760	        boolean inUse = this.clinicService.findAllOwners().stream()
761	            .filter(existing -> !existing.isDeleted())
762	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
763	        if (inUse) {
764	            throw new DuplicateOwnerIdentityException(identityKey);
765	        }
766	    }
767	
768	    /**
769	     * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
770	     * that shares this owner's last name (compared case-insensitively with collapsed whitespace) and
771	     * postcode but carries a different (normalized) telephone; such an owner is not a hard duplicate
772	     * (its identity key differs) and is still created. When at least one soft match exists,
773	     * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the lowest-id match;
774	     * otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left unset.
775	     * <p>
776	     * A declared household member - an owner that acknowledged sharing an existing household via
777	     * {@code sharesHousehold} - is never flagged: having deliberately joined the household it is not a
778	     * suspected duplicate, so {@code possibleDuplicate} is set false without inspecting other owners.
779	     *
780	     * @param owner the owner being created, with its last name, postcode and normalized telephone resolved
781	     * @param declaredHouseholdMember whether the owner joined an existing household by acknowledging it
782	     */
783	    private void applyPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
784	        if (declaredHouseholdMember) {
785	            owner.setPossibleDuplicate(false);
786	            return;
787	        }
788	        String lastName = normalizeHouseholdField(owner.getLastName());
789	        String postcode = owner.getPostcode();
790	        String telephone = owner.getTelephone();
791	        Owner match = null;
792	        if (postcode != null && !postcode.isBlank()) {
793	            match = this.clinicService.findAllOwners().stream()
794	                .filter(existing -> !existing.isDeleted())
795	                .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName))
796	                .filter(existing -> postcode.equals(existing.getPostcode()))
797	                .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
798	                .min(java.util.Comparator.comparing(Owner::getId))
799	                .orElse(null);
800	        }
801	        if (match != null) {
802	            owner.setPossibleDuplicate(true);
803	            owner.setPossibleDuplicateOf(match.getId());
804	        } else {
805	            owner.setPossibleDuplicate(false);
806	        }
807	    }
808	
809	    /**
810	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
811	     * household member count} for the response.
812	     *
813	     * @param owner the owner to map
814	     * @return the mapped owner DTO
815	     */
816	    private OwnerDto toOwnerDto(Owner owner) {
817	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
818	        return ownerMapper.toOwnerDto(owner);
819	    }
820	
821	    /**
822	     * Counts the members of the given owner's household - the owners that share this owner's
823	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
824	     * is {@code null}) is its own sole member, so the count is one.
825	     *
826	     * @param owner the owner whose household is being sized
827	     * @return the number of owners sharing this owner's household (one when it has no household)
828	     */
829	    private int countHouseholdMembers(Owner owner) {
830	        String householdId = owner.getHouseholdId();
831	        if (householdId == null) {
832	            return 1;
833	        }
834	        return (int) this.clinicService.findAllOwners().stream()
835	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
836	            .count();
837	    }
838	
839	    /**
840	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
841	     * last name and a postcode: the {@code householdId} is derived deterministically from the
842	     * normalized last name and the postcode (see {@link #generateHouseholdId(String, String)}), so two
843	     * owners with the same last name and postcode always resolve to the same identifier and belong to
844	     * the same household automatically - no acknowledgement is needed to create the link.
845	     * <p>
846	     * When the owner supplies a postcode its {@code householdId} is always assigned. If that household
847	     * already has at least one member, the create is a household duplicate: it is rejected with a 409
848	     * unless {@code sharesHousehold} is true, in which case the owner is created as a declared member
849	     * of that household. An owner with no postcode belongs to no household and is left without an
850	     * identifier.
851	     *
852	     * @param owner the owner being created
853	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
854	     * @return {@code true} when the owner joined an existing household as a declared member, otherwise
855	     *         {@code false}
856	     * @throws DuplicateOwnerHouseholdException when the household already exists and the create did not
857	     *         acknowledge it via {@code sharesHousehold}
858	     */
859	    private boolean applyHousehold(Owner owner, Boolean sharesHousehold) {
860	        String postcode = owner.getPostcode();
861	        if (postcode == null || postcode.isBlank()) {
862	            return false;
863	        }
864	        String lastName = normalizeHouseholdField(owner.getLastName());
865	        String householdId = generateHouseholdId(lastName, postcode);
866	        owner.setHouseholdId(householdId);
867	        boolean hasExistingMember = this.clinicService.findAllOwners().stream()
868	            .filter(existing -> !existing.isDeleted())
869	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
870	        if (!hasExistingMember) {
871	            return false;
872	        }
873	        if (!Boolean.TRUE.equals(sharesHousehold)) {
874	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), postcode);
875	        }
876	        return true;
877	    }
878	
879	    /**
880	     * Builds the stable identifier shared by the members of one household. It is derived purely from
881	     * the normalized last name and the postcode, so every owner sharing a last name and postcode
882	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
883	     * two fields joined by a single '|'.
884	     *
885	     * @param normalizedLastName the household's last name, already normalized for comparison
886	     * @param postcode the household's postcode
887	     * @return the shared household identifier
888	     */
889	    private String generateHouseholdId(String normalizedLastName, String postcode) {
890	        String key = normalizedLastName + '|' + postcode;
891	        try {
892	            byte[] digest = MessageDigest.getInstance("SHA-256")
893	                .digest(key.getBytes(StandardCharsets.UTF_8));
894	            StringBuilder hex = new StringBuilder();
895	            for (byte b : digest) {
896	                hex.append(String.format("%02X", b));
897	                if (hex.length() >= 12) {
898	                    break;
899	                }
900	            }
901	            return hex.substring(0, 12);
902	        } catch (NoSuchAlgorithmException e) {
903	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
904	        }
905	    }
906	
907	    /**
908	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
909	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
910	     * the owner's normalized telephone and last name.
911	     *
912	     * @param input the string to digest
913	     * @param length the number of leading upper-case hex characters to return
914	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
915	     */
916	    private String sha256UpperHex(String input, int length) {
917	        try {
918	            byte[] digest = MessageDigest.getInstance("SHA-256")
919	                .digest(input.getBytes(StandardCharsets.UTF_8));
920	            StringBuilder hex = new StringBuilder();
921	            for (byte b : digest) {
922	                hex.append(String.format("%02X", b));
923	                if (hex.length() >= length) {
924	                    break;
925	                }
926	            }
927	            return hex.substring(0, length);
928	        } catch (NoSuchAlgorithmException e) {
929	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
930	        }
931	    }
932	
933	    /**
934	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
935	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
936	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
937	     * expands common abbreviations.
938	     *
939	     * @param value the raw last name, or {@code null}
940	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
941	     */
942	    private String normalizeHouseholdField(String value) {
943	        if (value == null) {
944	            return "";
945	        }
946	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
947	    }
948	}
