17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.web.bind.MethodArgumentNotValidException;
36	import org.springframework.web.bind.annotation.ControllerAdvice;
37	import org.springframework.web.bind.annotation.ExceptionHandler;
38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
56	    private static final String ERROR_DUPLICATE_EMAIL = "An owner with the given email already exists";
57	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the given last name and address already exists";
58	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity already exists";
59	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
60	    private static final String ERROR_DAILY_LIMIT_REACHED = "The maximum number of owners for today has already been reached";
61	
62	    /**
63	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
64	     * class.
65	     *
66	     * @param e     Object referring to the thrown exception.
67	     * @param status HTTP response status.
68	     * @param url URL request.
69	     */
70	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
71	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
72	        problemDetail.setType(URI.create(url.toString()));
73	        problemDetail.setTitle(e.getClass().getSimpleName());
74	        problemDetail.setDetail(detail);
75	        problemDetail.setProperty("timestamp", Instant.now());
76	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
77	        return problemDetail;
78	    }
79	
80	    /**
81	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
82	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
83	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
84	     * would catch it and report an authorization failure as a 500.
85	     *
86	     * @param e The {@link AccessDeniedException} to propagate
87	     * @throws AccessDeniedException always
88	     */
89	    @ExceptionHandler(AccessDeniedException.class)
90	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
91	        throw e;
92	    }
93	
94	    /**
95	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
96	     *
97	     * @param e The {@link Exception} to be handled
98	     * @param request {@link HttpServletRequest} object referring to the current request.
99	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
100	     */
101	    @ExceptionHandler(Exception.class)
102	    @ResponseBody
103	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
104	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
105	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
106	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
107	        return ResponseEntity.status(status).body(detail);
108	    }
109	
110	    /**
111	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
112	     * method returns a 404 Not Found status if an entity does not exist.
113	     *
114	     * @param e The {@link DataIntegrityViolationException} to be handled
115	     * @param request {@link HttpServletRequest} object referring to the current request.
116	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
117	     */
118	    @ExceptionHandler(DataIntegrityViolationException.class)
119	    @ResponseBody
120	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
121	        logger.warn("Data integrity violation at {} {}: {}",
122	            request.getMethod(),
123	            request.getRequestURI(),
124	            e.getMessage());
125	        logger.debug("Data integrity violation stacktrace", e);
126	        HttpStatus status = HttpStatus.NOT_FOUND;
127	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
128	        return ResponseEntity.status(status).body(detail);
129	    }
130	
131	    /**
132	     * Handles exception thrown by Bean Validation on controller methods parameters
133	     *
134	     * @param e The {@link MethodArgumentNotValidException} to be handled
135	     * @param request {@link HttpServletRequest} object referring to the current request.
136	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
137	     */
138	    @ExceptionHandler(MethodArgumentNotValidException.class)
139	    @ResponseBody
140	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
141	        HttpStatus status = HttpStatus.BAD_REQUEST;
142	        BindingErrorsResponse errors = new BindingErrorsResponse();
143	        BindingResult bindingResult = e.getBindingResult();
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
145	        if (bindingResult.hasErrors()) {
146	            errors.addAllErrors(bindingResult);
147	            List<String> missingFields = bindingResult.getFieldErrors().stream()
148	                .filter(fieldError -> {
149	                    Object rejected = fieldError.getRejectedValue();
150	                    return rejected == null || (rejected instanceof String value && value.isBlank());
151	                })
152	                .map(fieldError -> fieldError.getField())
153	                .distinct()
154	                .toList();
155	            detail.setProperty("errors", missingFields);
156	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
157	                .map(fieldError -> {
158	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
159	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
160	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
161	                        fieldError.getField(),
162	                        defaultMessage,
163	                        rejectedValue);
164	                    return new ValidationMessageDto(message)
165	                        .putAdditionalProperty("field", fieldError.getField())
166	                        .putAdditionalProperty("rejectedValue", rejectedValue)
167	                        .putAdditionalProperty("defaultMessage", defaultMessage);
168	                })
169	                .toList();
170	            logger.debug("Validation error at {} {}: {}",
171	                request.getMethod(),
172	                request.getRequestURI(),
173	                bindingResult.getFieldErrors());
174	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
175	            return ResponseEntity.status(status).body(detail);
176	        }
177	        return ResponseEntity.status(status).body(detail);
178	    }
179	
180	    /**
181	     * Handles {@link MissingOwnerFieldsException} raised when an owner create/update request omits
182	     * or leaves blank one or more mandatory fields that Bean Validation does not otherwise reject.
183	     * Returns a 400 Bad Request whose {@code errors} array lists the name of each missing field.
184	     *
185	     * @param e The {@link MissingOwnerFieldsException} to be handled
186	     * @param request {@link HttpServletRequest} object referring to the current request.
187	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
188	     */
189	    @ExceptionHandler(MissingOwnerFieldsException.class)
190	    @ResponseBody
191	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
192	        logger.debug("Missing owner fields at {} {}: {}",
193	            request.getMethod(),
194	            request.getRequestURI(),
195	            e.getMissingFields());
196	        HttpStatus status = HttpStatus.BAD_REQUEST;
197	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
198	        detail.setProperty("errors", e.getMissingFields());
199	        return ResponseEntity.status(status).body(detail);
200	    }
201	
202	    /**
203	     * Handles {@link InvalidOwnerFieldsException} raised when an owner create/update request supplies
204	     * a mandatory field whose value violates a business rule that Bean Validation does not otherwise
205	     * reject (for example a telephone that is not exactly ten digits after non-digit characters are
206	     * stripped). Returns a 400 Bad Request whose {@code errors} array lists the name of each field.
207	     *
208	     * @param e The {@link InvalidOwnerFieldsException} to be handled
209	     * @param request {@link HttpServletRequest} object referring to the current request.
210	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
211	     */
212	    @ExceptionHandler(InvalidOwnerFieldsException.class)
213	    @ResponseBody
214	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
215	        logger.debug("Invalid owner fields at {} {}: {}",
216	            request.getMethod(),
217	            request.getRequestURI(),
218	            e.getInvalidFields());
219	        HttpStatus status = HttpStatus.BAD_REQUEST;
220	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
221	        detail.setProperty("errors", e.getInvalidFields());
222	        return ResponseEntity.status(status).body(detail);
223	    }
224	
225	    /**
226	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner create request supplies a
227	     * telephone whose normalized form is already used by another owner. Returns a 409 Conflict.
228	     *
229	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
230	     * @param request {@link HttpServletRequest} object referring to the current request.
231	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
232	     */
233	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
234	    @ResponseBody
235	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
236	        logger.debug("Duplicate owner telephone at {} {}: {}",
237	            request.getMethod(),
238	            request.getRequestURI(),
239	            e.getTelephone());
240	        HttpStatus status = HttpStatus.CONFLICT;
241	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
242	        detail.setProperty("errors", List.of("telephone"));
243	        return ResponseEntity.status(status).body(detail);
244	    }
245	
246	    /**
247	     * Handles {@link DuplicateOwnerEmailException} raised when an owner create request supplies an
248	     * email whose lower-cased form is already used by another owner. Returns a 409 Conflict.
249	     *
250	     * @param e The {@link DuplicateOwnerEmailException} to be handled
251	     * @param request {@link HttpServletRequest} object referring to the current request.
252	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
253	     */
254	    @ExceptionHandler(DuplicateOwnerEmailException.class)
255	    @ResponseBody
256	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerEmailException(DuplicateOwnerEmailException e, HttpServletRequest request) {
257	        logger.debug("Duplicate owner email at {} {}: {}",
258	            request.getMethod(),
259	            request.getRequestURI(),
260	            e.getEmail());
261	        HttpStatus status = HttpStatus.CONFLICT;
262	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_EMAIL);
263	        detail.setProperty("errors", List.of("email"));
264	        return ResponseEntity.status(status).body(detail);
265	    }
266	
267	    /**
